/**
   * User Controller
   * @param {object} db
   * @param {instance} user
   */
export default class {
  constructor(db, user, auth) {
    this.db = db;
    this.user = user;
    this.auth = auth;
  }

  /**
     * Create A User
     * @param {object} req
     * @returns {object} user object
     */
  async create(req) {
    const {
      email, username, password, phone, address,
    } = req.body;
    if (!username || !email || !password) {
      return { status: 'fail', statusCode: 400, message: 'Please input username, email and password' };
    }
    if (!username || username.toString().startsWith('0') || typeof username !== 'string' || username.trim().length === 0) {
      return { status: 'fail', statusCode: 400, message: 'Please input valid username' };
    }

    this.user.email = email.trim().toLowerCase();
    this.user.username = username.trim().toLowerCase();
    this.user.password = password;

    if (!this.user.isValidEmail()) {
      return { status: 'fail', statusCode: 400, message: 'Please enter a valid email address' };
    }
    if (this.user.isValidPassword() !== 'true') {
      return { status: 'fail', statusCode: 400, message: this.user.isValidPassword() };
    }
    this.user.password = this.auth.hashPassword(this.user.password);
    this.user.phone = phone;
    this.user.address = address;
    this.user.createdDate = new Date();
    this.user.modifiedDate = new Date();

    const createQuery = `INSERT INTO
          users(username, email, password, phone, address, created_date, modified_date)
          VALUES($1, $2, $3, $4, $5, $6, $7)
          returning *`;
    const values = [
      this.user.username,
      this.user.email,
      this.user.password,
      this.user.phone,
      this.user.address,
      this.user.createdDate,
      this.user.modifiedDate,
    ];
    try {
      const { rows } = await this.db.query(createQuery, values);
      this.user.userId = rows[0].userid;
      const token = this.auth.generateToken(
        rows[0].userid, rows[0].username, rows[0].email, rows[0].role,
      );
      this.user.password = undefined;
      return {
        status: 'success', statusCode: 201, message: 'Signup successful', user: this.user, token,
      };
    } catch (error) {
      console.error('ERRO NO CREATE USER:', error);
      console.error('STACK:', error.stack);
      if (error.routine === '_bt_check_unique') {
        let message = '';
        if (error.detail.includes('username')) {
          message = `Username ${this.user.username} already exists`;
        }
        if (error.detail.includes('email')) {
          message = `Email address ${this.user.email} already exists`;
        }
        if (error.detail.includes('phone')) {
          message = `Phone number ${this.user.phone} already exists`;
        }
        return { status: 'fail', statusCode: 409, message };
      }
      return { status: 'fail', statusCode: 500, error: error.message };
    }
  }

  /**
    * Login
    * @param {object} req
    * @returns {object} user object
    */
  async login(req) {
    const { usernameEmail, password } = req.body;
    if ((!usernameEmail) || !password || Object.keys(req.body).length > 2) {
      return { status: 'fail', statusCode: 400, message: 'Please login with either (username or email) and password' };
    }
    if (usernameEmail) usernameEmail.trim().toLowerCase();
    const text = 'SELECT * FROM users WHERE email = $1 OR username = $1';
    try {
      const { rows } = await this.db.query(
        text, [usernameEmail.trim().toLowerCase()],
      );
      if (!rows[0] || !this.auth.comparePassword(password, rows[0].password)) {
        return { status: 'fail', statusCode: 400, message: 'The credentials you provided are incorrect' };
      }
      const { userid, username, email, role } = rows[0];
      const token = this.auth.generateToken(userid, username, email, role);
      rows[0].password = undefined;
      return {
        status: 'success', statusCode: 200, message: 'Login successful', user: rows[0], token,
      };
    } catch (error) {
      return { status: 'fail', statusCode: 500, error: error.message };
    }
  }

  /**
   * Get All orders/specific user
   * @param {object} request
   * @returns {object} orders
   */
  async findOrdersByUserId(req) {
    try {
      const getUserQuery = 'SELECT * FROM users WHERE userId = $1';
      const { rows } = await this.db.query(getUserQuery, [req.params.userId]);
      if (!rows[0]) {
        return { statusCode: 404, status: 'fail', message: 'User not found' };
      }
      const getAllOrdersQuery = 'SELECT * FROM orders WHERE userId = $1';
      const response = await this.db.query(getAllOrdersQuery, [req.params.userId]);
      const message = response.rowCount === 0 ? 'User has not made an order yet' : 'Orders retrieved successfully';
      return {
        statusCode: 200, status: 'success', message, orders: response.rows,
      };
    } catch (error) {
      return { statusCode: 500, status: 'fail', error: error.message };
    }
  }

  async read() {
    const getAllQuery = 'SELECT * FROM users';
    try {
      const { rows, rowCount } = await this.db.query(getAllQuery);
      return {
        status: 'success', statusCode: 200, message: `${rowCount} Users retrieved successfully`, users: rows, totalUsers: rowCount,
      };
    } catch (error) {
      return { status: 'fail', statusCode: 500, message: error.message };
    }
  }
}

import express from 'express';
import logger from 'morgan';
import path from 'path';
import upload from './helpers/upload';
import AuthC from './controllers/authController';

// adicionei um comentario no server.js

export default (orderC, userC, menuC) => {
  const server = express();
  const prefix = '/api/v1';

  /** TOP LEVEL MIDDLEWARES ** */
  server.use(logger('dev'));
  server.use(express.json());
  server.use(express.urlencoded({ extended: true }));

  // GET /orders
  server.get(`${prefix}/orders`, AuthC.verifyAdminToken, (_req, res) => orderC.read().then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(500).json({ status: 'fail', message: err.error || err.message })));

  // GET /orders:orderId
  server.get(`${prefix}/orders/:orderId`, AuthC.verifyAdminToken, (req, res) => {
    orderC.read(req).then(result => res.status(result.statusCode).json(result))
      .catch(err => res.status(404)
        .json({ status: 'fail', message: err.error || err.message }));
  });

  // POST /orders
  server.post(`${prefix}/orders`, AuthC.verifyToken, (req, res) => orderC.create(req)
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500)
      .json({ status: 'fail', error: err.message || err.error })));
  // PUT /orders/:orderId
  server.put(`${prefix}/orders/:orderId`, AuthC.verifyAdminToken, (req, res) => {
    orderC.updateStatus(req)
      .then(result => res.status(result.statusCode).json(result))
      .catch(err => res.status(400)
        .json({ status: 'fail', message: err.error || err.message }));
  });

  // DELETE /orders/:orderId
  server.delete(`${prefix}/orders/:orderId`, (req, res) => orderC.delete(req.params.orderId)
    .then(result => res.status(200).json(result))
    .catch(() => res.sendStatus(404)));

  // ****** USER ROUTES **** //
  // SIGNUP /user
  server.post(`${prefix}/auth/signup`, (req, res) => userC.create(req)
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500)
      .json({ status: 'fail', error: err.message || err.error })));

  // LOGIN /user
  server.post(`${prefix}/auth/login`, (req, res) => userC.login(req)
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500)
      .json({ status: 'fail', error: err.message || err.error })));

  // GET all order-history by userId
  server.get(`${prefix}/users/:userId/orders`, AuthC.verifyToken, (req, res) => userC.findOrdersByUserId(req)
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500)
      .json({ status: err.statusCode, error: err.error || err.message })));

  server.get(`${prefix}/users`, AuthC.verifyAdminToken, (_req, res) => userC.read().then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(500).json({ status: 'fail', message: err.error || err.message })));


  // ****** MENU ROUTES **** //
  server.get(`${prefix}/menu`, AuthC.verifyToken, (_req, res) => menuC.read()
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500).json(err)));

  server.post(`${prefix}/menu`, AuthC.verifyAdminToken, upload.single('img'), (req, res) => menuC.create(req)
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500).json(err)));

  server.put(`${prefix}/menu/:foodId`, AuthC.verifyAdminToken, upload.single('img'), (req, res) => {
    menuC.update(req)
      .then(result => res.status(result.statusCode).json(result))
      .catch(err => res.status(err.statusCode || 500)
        .json({ status: 'fail', message: err.error || err.message }));
  });

  server.delete(`${prefix}/menu/:foodId`, AuthC.verifyAdminToken, (req, res) => menuC.delete(req)
    .then(result => res.status(result.statusCode).json(result))
    .catch(err => res.status(err.statusCode || 500).json(err)));


  server.get('/api/v1', (req, res) => res.status(200).json({ message: 'Welcome to API version 1 of FastFoodFast' }));

  // ==========POWER FRONT-END PAGES===============//
  const uiPath = path.join(__dirname, '../../UI');
  server.use(express.static(uiPath));
  server.use('/uploads', express.static('uploads'));

  server.get('/', (_req, res) => {
    res.sendFile(`${uiPath}/templates/index.html`);
  });
  server.get('/index', (_req, res) => {
    res.sendFile(`${uiPath}/templates/index.html`);
  });
  server.get('/userIndex', (_req, res) => {
    res.sendFile(`${uiPath}/templates/userIndex.html`);
  });

  server.get('/menu', (_req, res) => {
    res.sendFile(`${uiPath}/templates/menu.html`);
  });
  server.get('/userMenu', (_req, res) => {
    res.sendFile(`${uiPath}/templates/userMenu.html`);
  });

  server.get('/signup', (_req, res) => {
    res.sendFile(`${uiPath}/templates/signup.html`);
  });
  server.get('/login', (_req, res) => {
    res.sendFile(`${uiPath}/templates/login.html`);
  });
  server.get('/admin', (_req, res) => {
    res.sendFile(`${uiPath}/templates/admin.html`);
  });
  server.get('/history', (_req, res) => {
    res.sendFile(`${uiPath}/templates/history.html`);
  });

  // CATCH ALL OTHER ROUTES
  server.get('*', (req, res) => res.status(404).json({ message: 'Welcome to Fast Food Fast', error: 'Sorry, this route is not available' }));
  server.post('*', (req, res) => res.status(404).json({ message: 'Welcome to Fast Food Fast', error: 'Sorry, this route is not available' }));

  return server;
};

import multer from 'multer';

const storage = multer.diskStorage({
  destination(req, file, cb) {
    cb(null, './uploads/');
  },
  filename(req, file, cb) {
    const date = new Date().toISOString().replace(/:/g, '-');
    cb(null, `${date}_${file.originalname.trim()}`);
  },
});

const fileFilter = (req, file, cb) => {
  if (file.mimetype === 'image/jpeg' || file.mimetype === 'image/png') {
    cb(null, true);
  } else {
    cb(null, false);
  }
};
const upload = multer({
  storage,
  limits: {
    fileSize: 1024 * 1024 * 5,
  },
  fileFilter,
});

export default upload;

import jwt from 'jsonwebtoken';

const authController = {
  // Adapted from https://www.codementor.io/olawalealadeusi896/building-a-simple-api-with-nodejs-expressjs-postgresql-db-and-jwt-3-mke10c5c5
  /**
   * Verify Token
   * @param {object} req
   * @param {object} res
   * @param {object} next
   * @returns {object|void} response object
   */
  async verifyToken(req, res, next) {
    const token = req.headers['x-access-token'];
    if (!token) {
      return res.status(401).json({ error: { status: 'fail', statusCode: 401, message: 'Token is not provided' } });
    }
    try {
      const decoded = await jwt.verify(token, 'fastFoodFast');
      req.user = { userId: decoded.userId, username: decoded.username, email: decoded.email };
      return next();
    } catch (error) {
      return res.status(500).json({ error: { status: 'fail', statusCode: 500, message: error.message } });
    }
  },

  async verifyAdminToken(req, res, next) {
    const token = req.headers['x-access-token'];
    if (!token) {
      return res.status(401).json({ status: 'fail', statusCode: 401, message: 'Please provide a token' });
    }
    try {
      const decoded = await jwt.verify(token, 'fastFoodFast');

      if (decoded.role !== 'admin') {
        return res.status(403).json({ status: 'fail', statusCode: 403, message: 'Sorry, only admins are authorized' });
      }
      req.user = { userId: decoded.userId, username: decoded.username, email: decoded.email };
      return next();
    } catch (error) {
      return res.status(500).json({ status: 'fail', statusCode: 400, message: error.message });
    }
  },
};

export default authController;

